def ensure_workbook(path):
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        return path
    data=json.loads(zlib.decompress(base64.b85decode(PAYLOAD.encode())).decode())
    with pd.ExcelWriter(path, engine="openpyxl") as w:
        for sheet, obj in data.items():
            pd.DataFrame(obj["records"], columns=obj["columns"]).to_excel(w, sheet_name=sheet[:31], index=False)
    return path
